<script lang="ts">
	import Slider from '$lib/components/controls/Slider.svelte';
	import { adamStep, adamWStep, createAdamState } from '$lib/math/adam.js';
	let alpha=$state(.05); let decay=$state(.1); let steps=$state(20);
	const comparison=$derived.by(()=>{let a=[2],w=[2],sa=createAdamState(1),sw=createAdamState(1);for(let i=0;i<steps;i++){const g=[a[0]*.15];const ra=adamStep(a,g,sa,{alpha,beta1:.9,beta2:.999,epsilon:1e-8});const rw=adamWStep(w,[w[0]*.15],sw,{alpha,beta1:.9,beta2:.999,epsilon:1e-8},decay);a=ra.theta;sa=ra.state;w=rw.theta;sw=rw.state;}return {a:a[0],w:w[0]};});
</script>
<div class="demo"><div class="controls"><Slider bind:value={alpha} min={.01} max={.2} step={.01} label="α"/><Slider bind:value={decay} min={0} max={.5} step={.01} label="λ / weight decay"/><Slider bind:value={steps} min={1} max={60} step={1} label="itérations"/></div><div class="cards"><div><b>Adam + pénalité L2</b><strong>{comparison.a.toFixed(4)}</strong><span>la pénalité entre dans le gradient et est normalisée</span></div><div><b>AdamW</b><strong>{comparison.w.toFixed(4)}</strong><span>la décroissance est découplée : (1 − αλ)θ</span></div></div><p class="note">Changer α modifie l’interaction entre la pénalité L2 et la normalisation adaptative ; avec AdamW, le terme de decay reste explicite.</p></div>
<style>.demo{display:grid;gap:1rem}.controls{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.cards{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.cards div{display:grid;gap:.5rem;padding:1rem;border:1px solid var(--color-border);border-radius:var(--radius-md)}.cards strong{font:1.4rem var(--font-mono);color:var(--color-positive)}.cards span,.note{color:var(--color-text-muted);font-size:.9rem}@media(max-width:650px){.controls,.cards{grid-template-columns:1fr}}</style>
